class SettlementLimitOffsetPagination(LimitOffsetPagination):
    default_limit = 50
    max_limit = 200

class MerchantSettlementListView(generics.ListAPIView):
    serializer_class = SettlementLedgerSerializer
    pagination_class = SettlementLimitOffsetPagination
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        merchant_id = self.request.query_params.get('merchant_id')
        user_merchants = self.request.user.merchants.values_list('id', flat=True)
        if merchant_id:
            if int(merchant_id) not in user_merchants:
                raise PermissionDenied("Unauthorized merchant ID.")
            return SettlementLedger.objects.filter(merchant_id=merchant_id)
        return SettlementLedger.objects.filter(merchant_id__in=user_merchants)
